lindel.roundtrip:
SELECT hilbert_decode(
  hilbert_encode([10, 20]::UINTEGER[2]),
  2, false, true
) AS point;
-- [10, 20]

lindel.filter:
SELECT * FROM 'points.parquet'
WHERE x BETWEEN 1 AND 3
  AND y BETWEEN 1 AND 6;

stochastic.tails:
-- P(X >= 5), Poisson(rate = 2.5)
SELECT dist_poisson_cdf_complement(2.5, 4);
-- 0.10882198108584878

-- P(X <= 5), Binomial(n = 10, p = 0.3)
SELECT dist_binomial_cdf(10, 0.3, 5);
-- 0.9526510126000001

stochastic.monte_carlo:
WITH draws AS MATERIALIZED (
  SELECT
    dist_uniform_real_sample(-1, 1) AS x,
    dist_uniform_real_sample(-1, 1) AS y
  FROM range(100000)
)
SELECT 4.0 * AVG(
  (x*x + y*y <= 1)::INTEGER
) AS pi_estimate
FROM draws;
